// GEO:END

const LABEL_MIN_AREA = 1400;   // municipalities smaller than this (SVG units²) get a callout in the sea
const CALLOUT_W = 118;         // room on the east side for callouts (chip = CALLOUT_W - 14)
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

function parse(d) {
  if (typeof d === 'string') { try { return JSON.parse(d); } catch { return {}; } }
  return d && typeof d === 'object' ? d : {};
}
function tone(v, target) {
  if (v == null || Number.isNaN(Number(v))) return '#5b5560';
  if (v >= target + 5) return '#2f9e6b';
  if (v >= target) return '#c9a227';
  if (v >= target - 5) return '#e08a2e';
  return '#d0454c';
}
const fmt = v => (v == null || Number.isNaN(Number(v)) ? '–' : String(Math.round(Number(v))));

// Stack callouts beside the map, each as close to its municipality's latitude as the others allow.
function stackCallouts(items, top, bottom, gap) {
  items.sort((a, b) => a.cy - b.cy);
  items.forEach(it => { it.ly = it.cy; });
  for (let pass = 0; pass < 60; pass++) {
    for (let i = 1; i < items.length; i++) {
      const d = items[i].ly - items[i - 1].ly;
      if (d < gap) { const push = (gap - d) / 2; items[i - 1].ly -= push; items[i].ly += push; }
    }
    items.forEach(it => { it.ly = Math.max(top, Math.min(bottom, it.ly)); });
  }
  return items;
}

let current = null;
let selected = null;

function render(props) {
  current = props || {};
  const data = parse(current.data);
  const root = document.getElementById('ua-custom-block');
  if (!root) return;
  const regions = Array.isArray(data.regions) ? data.regions : [];
  const target = Number(data.target ?? 80);
  const unit = data.unit || '';
  if (data.selected !== undefined) selected = data.selected;
  if (!regions.length) {
    root.innerHTML = '<div class="pm-root pm-empty">Bind data.regions to show the map.</div>';
    return;
  }
  const byCode = Object.fromEntries(regions.map(r => [r.code, r]));
  const shapes = Object.entries(GEO.regions);
  const areas = shapes.map(([code, g]) => {
    const r = byCode[code] || { code, name: code };
    const on = selected === code;
    return `<path class="pm-area${on ? ' on' : ''}" data-code="${esc(code)}" d="${g.d}" fill="${tone(r.value, target)}"
      tabindex="0" role="button" aria-label="${esc(r.name)} ${esc(r.value ?? '')}${esc(unit)}"><title>${esc(r.name)} · ${esc(r.value ?? '–')}${esc(unit)}</title></path>`;
  });
  // the selected outline is drawn again on top so its full border shows
  const top = selected && GEO.regions[selected] ? `<path class="pm-sel" d="${GEO.regions[selected].d}"/>` : '';
  const inside = [], callouts = [];
  for (const [code, g] of shapes) {
    const r = byCode[code];
    if (!r) continue;
    (g.area >= LABEL_MIN_AREA ? inside : callouts).push({ code, g, r, cx: g.cx, cy: g.cy });
  }
  const inLabels = inside.map(({ g, r }) => `<g class="pm-lbl" pointer-events="none">
      <text class="pm-val" x="${g.cx}" y="${g.cy}">${esc(fmt(r.value))}</text>
      <text class="pm-name" x="${g.cx}" y="${(g.cy + 12).toFixed(1)}">${esc(r.name)}</text></g>`).join('');
  const lx = GEO.w + 14;
  const outLabels = stackCallouts(callouts, 12, GEO.h - 12, 26).map(({ code, g, r, ly }) => `<g class="pm-call${selected === code ? ' on' : ''}" data-code="${esc(code)}" role="button" tabindex="0">
      <polyline class="pm-lead" points="${g.cx},${g.cy} ${(GEO.w + 4).toFixed(1)},${ly.toFixed(1)} ${(lx - 3).toFixed(1)},${ly.toFixed(1)}"/>
      <circle class="pm-pin" cx="${g.cx}" cy="${g.cy}" r="1.8"/>
      <rect class="pm-chip" x="${lx}" y="${(ly - 9).toFixed(1)}" width="${CALLOUT_W - 14}" height="18" rx="9"/>
      <circle cx="${lx + 9}" cy="${ly.toFixed(1)}" r="5" fill="${tone(r.value, target)}"/>
      <text class="pm-cname" x="${lx + 18}" y="${(ly + 3.5).toFixed(1)}">${esc(r.name)}</text>
      <text class="pm-cval" x="${lx + CALLOUT_W - 22}" y="${(ly + 3.5).toFixed(1)}">${esc(fmt(r.value))}</text></g>`).join('');
  const ranked = [...regions].sort((a, b) => Number(b.value) - Number(a.value));
  const vals = ranked.map(r => Number(r.value)).filter(v => !Number.isNaN(v));
  const lo = Math.min(target - 15, ...vals), hi = Math.max(target + 10, ...vals);
  const pct = v => Math.max(4, ((Number(v) - lo) / (hi - lo)) * 100);
  const list = ranked.map(r => `<button class="pm-row${selected === r.code ? ' on' : ''}" data-code="${esc(r.code)}" type="button">
      <span class="pm-rname">${esc(r.name)}</span>
      <span class="pm-track"><i style="width:${pct(r.value).toFixed(1)}%;background:${tone(r.value, target)}"></i><b style="left:${pct(target).toFixed(1)}%"></b></span>
      <span class="pm-rval">${esc(Number(r.value).toFixed(1))}${esc(unit)}</span></button>`).join('');
  const sel = byCode[selected];
  const vw = GEO.w + CALLOUT_W + 12, vh = GEO.h + 12;
  root.innerHTML = `<div class="pm-root">
    <div class="pm-head"><span class="pm-title">${esc(data.title || 'Regions')}</span>
      <span class="pm-legend"><i style="background:#2f9e6b"></i>≥${target + 5}<i style="background:#c9a227"></i>≥${target}<i style="background:#e08a2e"></i>≥${target - 5}<i style="background:#d0454c"></i>below</span></div>
    <div class="pm-body">
      <svg viewBox="-6 -6 ${vw.toFixed(0)} ${vh.toFixed(0)}" class="pm-svg" style="aspect-ratio:${(vw / vh).toFixed(3)}" preserveAspectRatio="xMidYMid meet">
        <g class="pm-land">${areas.join('')}</g>${top}${inLabels}${outLabels}</svg>
      <div class="pm-list"><div class="pm-lhead">Ranked · target ${esc(target)}${esc(unit)}</div>${list}</div>
    </div>
    <div class="pm-foot"><div>${sel ? `<b>${esc(sel.name)}</b> · ${esc(sel.value)}${esc(unit)} · risk ${esc(sel.risk)}<br><span>${esc(sel.note || '')}</span>` : '<span>Select a municipality on the map or in the list.</span>'}</div>
      <span class="pm-credit">Boundaries: geoBoundaries (CC BY 4.0)</span></div>
  </div>`;
  const pick = code => {
    selected = selected === code ? null : code;
    const r = byCode[code] || {};
    // ctx keys become {{ code }}, {{ name }}, {{ value }} in the block's onChange handler
    current.emitOnChange?.({ code: selected || '', name: selected ? r.name : '', value: selected ? r.value : null }, { code: selected || '' });
    current.updateState?.({ selected: selected || '' });
    render(current);
  };
  root.querySelectorAll('.pm-area, .pm-call, .pm-row').forEach(el => {
    const code = el.getAttribute('data-code');
    el.addEventListener('click', () => pick(code));
    if (el.tagName !== 'BUTTON') el.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(code); } });
  });
}

window.renderComponent = render;
export default render;
